(function(E){ const x = E["int-m3"] = E["int-m3"] || {units:{}}; x.units["int-9"] = {"grammar":{"id":"c-int-9-g","level":"B1","course":"interview","unit":"int-9","title":"Asking politely: I was hoping, Would it be possible","titleTr":"Kibarca istemek: I was hoping, Would it be possible","titleFa":"درخواست مؤدبانه: I was hoping و Would it be possible","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["I was hoping + could","I was hoping you could cover my flight."],["I was wondering if...","I was wondering if overtime is paid."],["Would it be possible to + verb?","Would it be possible to start on 3 April?"]]},"wrong":"I want that you pay my flight.","right":"I was hoping you could pay for my flight.","blank":{"sentence":"Would it be possible ___ my contract before I sign the offer?","word":"to see","distractors":["to seeing","seeing"]},"wrong2":"Would it be possible to starting on 3 April?","right2":"Would it be possible to start on 3 April?","blank2":{"sentence":"I was ___ if overtime is paid for night shifts.","word":"wondering","distractors":["wonder","wondered"]},"expParts":{"rule":[{"en":"A soft request: I was hoping... could...","tr":"Yumuşak bir rica: I was hoping... could...","fa":"درخواست نرم: I was hoping... could...‎","ex":"I was hoping you could cover my flight."},{"en":"A soft question: I was wondering if...","tr":"Yumuşak bir soru: I was wondering if...","fa":"سؤال نرم: I was wondering if...‎","ex":"I was wondering if overtime is paid."},{"en":"Would it be possible to + verb?","tr":"Would it be possible to + fiil?","fa":"Would it be possible to + فعل؟","ex":"Would it be possible to start on 3 April?"}],"test":{"en":"Could you say it to a manager you respect? If it sounds like an order, start with 'I was hoping' or 'Would it be possible'.","tr":"Bunu saygı duyduğun bir yöneticiye söyleyebilir misin? Emir gibi duyuluyorsa 'I was hoping' ya da 'Would it be possible' ile başla.","fa":"می‌توانی همین را به مدیری که به او احترام می‌گذاری بگویی؟ اگر مثل دستور به نظر می‌رسد، با «I was hoping» یا «Would it be possible» شروع کن."},"contrast":{"en":"Turkish 'istiyorum ki ödeyesiniz' and Persian 'می‌خواهم که بپردازید' give the calque 'I want that you pay', which sounds rude. English softens with the past (I was hoping) and with would.","tr":"Türkçedeki 'istiyorum ki...' yapısı 'I want that you pay' gibi bir çeviriye yol açar ve kaba duyulur. İngilizce geçmiş zamanla (I was hoping) ve would ile yumuşatır.","fa":"ساختار «می‌خواهم که...» در فارسی به ترجمه‌ی «I want that you pay» می‌رسد که بی‌ادبانه است. انگلیسی با زمان گذشته (I was hoping) و با would لحن را نرم می‌کند."}},"errorWatch":[{"find":["i want that you","i want that the company"],"fix":{"en":"'I want that you...' sounds like an order. Try: 'I was hoping you could...' or 'Would it be possible to...?'","tr":"'I want that you...' emir gibi duyulur. Şunu dene: 'I was hoping you could...' ya da 'Would it be possible to...?'","fa":"«I want that you...‎» مثل دستور است. این را امتحان کن: «I was hoping you could...‎» یا «Would it be possible to...?‎»"}},{"find":["possible to starting","possible to seeing","possible to having","possible to getting","possible to changing","i was wonder","i was hope"],"fix":{"en":"Use 'possible to' + base verb ('possible to start') and 'I was wondering / I was hoping'.","tr":"'possible to' + yalın fiil ('possible to start') ve 'I was wondering / I was hoping' kullan.","fa":"بعد از possible to شکل ساده‌ی فعل بیاور («possible to start») و بگو «I was wondering / I was hoping»."}}]},"b2":{"id":"c-int-9-b2","level":"B2","track":"B2","course":"interview","unit":"int-9","title":"Offering a trade: If you could..., I'd be happy to...","titleTr":"Takas önermek: If you could..., I'd be happy to...","titleFa":"پیشنهاد معامله: If you could..., I'd be happy to...","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Proposal: If you could..., I'd...","If you could cover my flight, I'd be happy to start early."],["I'd be happy to + verb (with be)","I'd be happy to start on 28 March."],["Closing the deal: If + present, will","If you send the contract today, I will sign it on Monday."]]},"wrong":"If you could cover my flight, I would happy to start early.","right":"If you could cover my flight, I would be happy to start early.","blank":{"sentence":"If you could pay for the flight, I ___ happy to arrive a few days early.","word":"would be","distractors":["would","will"]},"wrong2":"If they could give me a single room, I would to pay a little more rent.","right2":"If they could give me a single room, I would pay a little more rent.","blank2":{"sentence":"If you ___ the contract today, I will sign it on Monday.","word":"send","distractors":["sent","sending"]},"useIn":{"en":"B2: in your reply to the offer, propose one small trade with 'If you could..., I'd be happy to...'.","tr":"B2: teklife cevabında 'If you could..., I'd be happy to...' ile küçük bir takas öner.","fa":"B2: در جوابت به پیشنهاد کار، با «If you could..., I'd be happy to...‎» یک معامله‌ی کوچک پیشنهاد بده."},"exitItem":{"from":"int-9","kind":"blank","prompt":"If you could move the start date to May, I ___ able to finish my notice period.","options":["would be","would","will"],"correct":0},"expParts":{"rule":[{"en":"Propose: If you could..., I would...","tr":"Öner: If you could..., I would...","fa":"پیشنهاد بده: If you could..., I would...‎","ex":"If you could cover my flight, I'd be happy to start early."},{"en":"I'd be happy to: don't drop be.","tr":"I'd be happy to: be'yi düşürme.","fa":"I'd be happy to: کلمه‌ی be را جا نینداز.","ex":"I'd be happy to start on 28 March."},{"en":"Close the deal: If + present, will.","tr":"Anlaşmayı bağla: If + present, will.","fa":"توافق را نهایی کن: If + حال ساده، will.","ex":"If you send the contract today, I will sign it on Monday."}],"test":{"en":"After would, is there an adjective (happy, able, glad)? Then add be.","tr":"would'dan sonra bir sıfat (happy, able, glad) mı var? O zaman be ekle.","fa":"بعد از would صفتی آمده (happy، able، glad)؟ پس be اضافه کن."},"contrast":{"en":"Turkish 'memnun olurum' and Persian 'خوشحال می‌شوم' are one verb, so be disappears: 'I would happy'. English needs would + be + happy.","tr":"Türkçede 'memnun olurum' tek bir fiildir; bu yüzden be kaybolur: 'I would happy'. İngilizcede would + be + happy gerekir.","fa":"«خوشحال می‌شوم» در فارسی یک فعل است؛ برای همین be جا می‌افتد: «I would happy». انگلیسی would + be + happy می‌خواهد."}},"errorWatch":[{"find":["would happy","would able","would glad","i'd happy","i'd glad","i'd able","will happy","will able"],"fix":{"en":"Add be: 'I would be happy to...', 'I'll be able to...'.","tr":"be ekle: 'I would be happy to...', 'I'll be able to...'.","fa":"be را اضافه کن: «I would be happy to...‎»، «I'll be able to...‎»."}},{"find":["would to pay","would to start","would to sign","would to move"],"fix":{"en":"After would, use the base verb without to: 'I would pay a little more.'","tr":"would'dan sonra to olmadan yalın fiil kullan: 'I would pay a little more.'","fa":"بعد از would فعل ساده بدون to بیاور: «I would pay a little more.‎»"}}]},"vocab":{"id":"c-int-9-v","level":"B1","category":"vocab","course":"interview","unit":"int-9","goals":["career"],"title":{"en":"The Offer","tr":"Teklif","fa":"پیشنهاد کار"},"cards":[{"word":"job offer","sentence":"They called with a job offer on Friday morning.","meaning":{"en":"When a company says it wants to give you the job.","tr":"iş teklifi.","fa":"پیشنهاد کار"}},{"word":"accept","sentence":"I'm happy to accept the offer.","meaning":{"en":"To say yes to something.","tr":"kabul etmek.","fa":"پذیرفتن؛ قبول کردن"}},{"word":"subject to","sentence":"The offer is subject to two good references.","meaning":{"en":"Only if something else happens first.","tr":"-e bağlı olarak, ...şartıyla.","fa":"مشروط به"}},{"word":"in writing","sentence":"Could you send me the offer in writing?","meaning":{"en":"Written down, not only said.","tr":"yazılı olarak.","fa":"به‌صورت کتبی"}},{"word":"basic salary","sentence":"The basic salary is 40,000 lira a month.","meaning":{"en":"Your pay before extra money such as allowances.","tr":"temel maaş.","fa":"حقوق پایه"}},{"word":"benefits","sentence":"The benefits include health insurance and a meal card.","meaning":{"en":"Things you get from a job as well as your pay.","tr":"yan haklar","fa":"مزایا"}},{"word":"overtime","sentence":"Is overtime paid for night shifts?","meaning":{"en":"Extra hours of work, often paid more.","tr":"fazla mesai.","fa":"اضافه‌کار"}},{"word":"probation","sentence":"The probation period is three months.","meaning":{"en":"The first months of a job, when the company checks that you are right for it.","tr":"deneme süresi.","fa":"دوره‌ی آزمایشی"}},{"word":"negotiate","sentence":"Basic pay is hard to negotiate for this role.","meaning":{"en":"To discuss something to reach an agreement.","tr":"pazarlık etmek, müzakere etmek.","fa":"مذاکره کردن"}},{"word":"sign","sentence":"Read every line before you sign.","meaning":{"en":"To write your name to agree to a document.","tr":"imzalamak.","fa":"امضا کردن"}}]},"judge":{"id":"c-int-9-j","course":"interview","unit":"int-9","type":"judge","title":{"en":"Answering an offer","tr":"Teklife cevap vermek","fa":"جواب دادن به پیشنهاد کار"},"prompt":"Five replies to a job offer, from five different people.","parts":["Thanks and shows interest","Gives a reason","One clear request"],"instruction":{"en":"Tap what each reply does. The strongest reply does all three.","tr":"Her cevabın ne yaptığına dokun. En güçlü cevap üçünü de yapar.","fa":"روی کاری که هر جواب می‌کند بزن. قوی‌ترین جواب هر سه را انجام می‌دهد."},"items":[{"by":"Graduate","answer":"Yes! Yes, I accept! Thank you so much!","present":["Thanks and shows interest"],"fix":{"en":"Be happy, but read first. Say: \"Thank you, that's great news. Could you send me the details in writing?\"","tr":"Sevin, ama önce oku. Şöyle de: \"Thank you, that's great news. Could you send me the details in writing?\"","fa":"خوشحال باش، ولی اول بخوان. بگو: «Thank you, that's great news. Could you send me the details in writing?»"}},{"by":"Engineer","answer":"I need 20% more, or I will take another offer.","present":["One clear request"],"fix":{"en":"An ultimatum gives them a reason to stop. Show you want the job and give your reason: \"I'd love to join you. Based on the market for this role, I was hoping for...\"","tr":"Ültimatom onlara durmak için neden verir. Bu işi istediğini göster ve nedenini söyle: \"I'd love to join you. Based on the market for this role, I was hoping for...\"","fa":"اولتیماتوم به آن‌ها دلیل می‌دهد که عقب بکشند. نشان بده این کار را می‌خواهی و دلیلت را بگو: «I'd love to join you. Based on the market for this role, I was hoping for...»"}},{"by":"AI tool","answer":"I am truly delighted by this incredible opportunity. However, I would appreciate any enhancement to the compensation package that you may be able to consider at this time.","present":["Thanks and shows interest"],"fix":{"en":"No number and no reason, so they cannot say yes to anything. Ask for one clear thing and say why.","tr":"Sayı yok, neden yok; yani evet diyecekleri bir şey yok. Tek bir net şey iste ve nedenini söyle.","fa":"نه عددی دارد نه دلیلی، پس چیزی نیست که به آن بله بگویند. یک چیز روشن بخواه و بگو چرا."}},{"by":"Nurse","answer":"Could you pay for parking? And another thing, my phone bill. Oh, and one more day of holiday? And can the start date change?","present":[],"fix":{"en":"Too many small requests, one after another. Choose what matters most, and put your requests in one message, most important first, each with a reason.","tr":"Peş peşe çok fazla küçük istek var. En önemlisini seç; isteklerini tek mesajda, en önemlisi başta olacak şekilde, her birini nedeniyle yaz.","fa":"خواسته‌های کوچک زیادی پشت هم آمده است. مهم‌ترین را انتخاب کن و خواسته‌هایت را در یک پیام بگو، مهم‌ترین اول و هر کدام با دلیلش."}},{"by":"Good model","answer":"Thank you so much, I'm very happy to join you. My contract requires four weeks' notice, so would it be possible to start on 3 April?","present":["Thanks and shows interest","Gives a reason","One clear request"],"fix":null}]},"speaking":{"id":"int-9","course":"interview","unit":"int-9","topic":{"en":"The offer call","tr":"Teklif görüşmesi","fa":"تماس پیشنهاد کار"},"warmup":{"en":"Think of a job you want. What matters most to you: pay, hours, start date or training? Put them in order.","tr":"İstediğin bir işi düşün. Senin için en önemlisi ne: maaş, çalışma saatleri, başlama tarihi, eğitim? Sıraya koy.","fa":"به کاری که می‌خواهی فکر کن. برایت کدام مهم‌تر است: حقوق، ساعت کار، تاریخ شروع یا آموزش؟ آن‌ها را به ترتیب اهمیت بچین."},"questions":[{"en":"Thank them warmly in one or two sentences, and ask for the details in writing.","tr":"Bir iki cümleyle içtenlikle teşekkür et ve ayrıntıları yazılı olarak iste.","fa":"در یکی دو جمله صمیمانه تشکر کن و بخواه جزئیات را کتبی بفرستند."},{"en":"Ask two questions about the package (for example overtime, insurance or probation).","tr":"Ücret paketiyle ilgili iki soru sor (örneğin fazla mesai, sigorta ya da deneme süresi).","fa":"دو سؤال درباره‌ی بسته‌ی حقوق و مزایا بپرس (مثلاً اضافه‌کاری، بیمه یا دوره‌ی آزمایشی)."},{"en":"Ask for one change, politely, with a reason: \"I was hoping...\" or \"Would it be possible to...?\"","tr":"Nedenini söyleyerek kibarca bir değişiklik iste: \"I was hoping...\" ya da \"Would it be possible to...?\"","fa":"مؤدبانه و با دلیل یک تغییر بخواه: «I was hoping...» یا «Would it be possible to...?»"},{"en":"Say when you will give your final answer, and close.","tr":"Son cevabını ne zaman vereceğini söyle ve bitir.","fa":"بگو جواب نهایی‌ات را کی می‌دهی و تمام کن."}],"followups":[{"en":"90, 60, 45 seconds: thanks, two questions, one request, close.","tr":"90, 60, 45 saniye: teşekkür, iki soru, bir istek, kapanış.","fa":"۹۰، ۶۰، ۴۵ ثانیه: تشکر، دو سؤال، یک خواسته، پایان."},{"en":"Now the other call: you did not get the job. Say three lines: \"Thank you for letting me know. Could you tell me one thing I could improve? I would like to stay in touch.\"","tr":"Şimdi öteki görüşme: işi alamadın. Üç satır söyle: \"Thank you for letting me know. Could you tell me one thing I could improve? I would like to stay in touch.\"","fa":"حالا تماس دیگر: کار را نگرفتی. سه خط بگو: «Thank you for letting me know. Could you tell me one thing I could improve? I would like to stay in touch.»"}],"expressions":[{"phrase":"Thank you so much for the offer.","meaning":{"en":"Your first sentence, before any question.","tr":"Her sorudan önce ilk cümlen.","fa":"جمله‌ی اولت، قبل از هر سؤال."}},{"phrase":"I was hoping... Would that be possible?","meaning":{"en":"Asks for a change without pushing.","tr":"Baskı yapmadan değişiklik ister.","fa":"بدون فشار یک تغییر می‌خواهد."}},{"phrase":"I'll get back to you by...","meaning":{"en":"Gives yourself time, with a date.","tr":"Bir tarih vererek kendine zaman tanır.","fa":"با گفتن تاریخ به خودت وقت می‌دهد."}}],"selfCheck":[{"en":"I thanked them before I asked anything.","tr":"Bir şey sormadan önce teşekkür ettim.","fa":"قبل از هر سؤالی تشکر کردم."},{"en":"I asked for the details in writing.","tr":"Ayrıntıları yazılı olarak istedim.","fa":"خواستم جزئیات را کتبی بفرستند."},{"en":"My request had a reason, and I did not threaten.","tr":"İsteğimin bir nedeni vardı ve tehdit etmedim.","fa":"خواسته‌ام دلیل داشت و تهدید نکردم."},{"en":"I gave a date for my final answer.","tr":"Son cevabım için bir tarih verdim.","fa":"برای جواب نهایی‌ام تاریخ دادم."}],"model":"Thank you so much for the offer. I'm very happy. Could you send me the details in writing? I have two questions. Is overtime paid for weekend work, and how long is the probation period? My notice period is four weeks, so I was hoping to start on 3 April. Would that be possible? I'll get back to you by Thursday."},"writing":{"id":"c-int-9-w","course":"interview","unit":"int-9","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"int-final-6","model":"Dear Ms Aksoy,\n\nThank you for your offer of the sales coordinator position. I am very happy, and I would like to accept in principle. I have two questions: is overtime paid for weekend work, and how long is the probation period?\n\nMy notice period is four weeks, so I was hoping to start on 3 April. Would that be possible?\n\nI will confirm my final answer by Thursday.\n\nKind regards,\nYour name","frame":"Dear ___,\n\nThank you for ___. I am very happy, and I would like to accept in principle. I have two questions: ___, and ___?\n\nMy ___, so I was hoping ___. Would that be possible?\n\nI will confirm ___ by ___.\n\nKind regards,\n___","words":[{"word":"in principle"},{"word":"probation"},{"word":"I was hoping"}],"minWords":70,"minSentences":5,"title":{"en":"Your reply to the written offer","tr":"Yazılı teklife cevabın","fa":"جواب تو به پیشنهاد کتبی"},"prompt":{"en":"You have a written job offer (real or imagined). Write a reply (70-100 words): thank them, say you are happy to accept in principle, ask two questions about the package, make one polite request and say when you will confirm. If you have none, use this: sales coordinator, start date 20 March, nothing said about overtime or probation.","tr":"Elinde yazılı bir iş teklifi var (gerçek ya da hayalî). Bir cevap yaz (70-100 kelime): teşekkür et, prensipte kabul etmekten memnun olduğunu söyle, ücret paketiyle ilgili iki soru sor, kibar bir ricada bulun ve ne zaman teyit edeceğini söyle. Teklifin yoksa şunu kullan: satış koordinatörü, başlama tarihi 20 Mart, fazla mesai ve deneme süresinden söz edilmemiş.","fa":"یک پیشنهاد کار کتبی داری (واقعی یا خیالی). یک جواب بنویس (۷۰ تا ۱۰۰ کلمه): تشکر کن، بگو در اصل با کمال میل قبولش می‌کنی، دو سؤال درباره‌ی بسته‌ی حقوق و مزایا بپرس، یک درخواست مؤدبانه مطرح کن و بگو کی تأیید نهایی را می‌فرستی. اگر پیشنهادی نداری، از این استفاده کن: هماهنگ‌کننده‌ی فروش، تاریخ شروع ۲۰ مارس، بدون هیچ حرفی درباره‌ی اضافه‌کاری یا دوره‌ی آزمایشی."},"rubric":["Task done: thanks, acceptance in principle, two questions, one request, a date to confirm","Organised: thanks, acceptance, questions, request, date, close","Language: \"I was hoping... could\"; \"Would it be possible to\" + verb; questions with the helper verb first","Tone: grateful and clear: asking, not demanding"],"rubricI18n":{"tr":["Görev: teşekkür, prensipte kabul, iki soru, bir rica, teyit için bir tarih","Düzen: teşekkür, kabul, sorular, rica, tarih, kapanış","Dil: \"I was hoping... could\"; \"Would it be possible to\" + fiil; yardımcı fiili başta olan sorular","Üslup: minnettar ve net: talep eden değil, rica eden"],"fa":["کامل بودن کار: تشکر، پذیرش در اصل، دو سؤال، یک درخواست، تاریخی برای تأیید","نظم: تشکر، پذیرش، سؤال‌ها، درخواست، تاریخ، پایان","زبان: «I was hoping... could»؛ «Would it be possible to» + فعل؛ سؤال‌هایی که فعل کمکی‌شان اول آمده","لحن: سپاسگزار و روشن؛ خواهش، نه طلبکاری"]}},"exit":{"id":"c-int-9-x","course":"interview","unit":"int-9","type":"exit","items":[{"from":"int-9","kind":"blank","prompt":"Would it be possible ___ the training in English?","options":["doing","to do","to doing"],"correct":1,"point":2},{"from":"int-9","kind":"mcq","prompt":"You did not get the job. Which reply is best?","options":["Thank you for telling me. What could I improve? I'd like to stay in touch.","Thank you, but I think your decision was wrong, and I would like a reason.","I see. Please keep my CV and call me if your first choice says no to you."],"correct":0,"point":1},{"from":"int-9","kind":"mcq","prompt":"You get a job offer by phone. Which answer is best?","options":["How much is the salary, and how soon do you need an answer from me?","Thank you, that's great news! Could you send me the details in writing?","OK. Yes, I accept. I can start whenever you want me to start."],"correct":1,"point":1},{"from":"int-8","kind":"blank","prompt":"If they ___ me the job, I would move within a month.","options":["offered","offer","will offer"],"correct":0},{"from":"int-6","kind":"mcq","prompt":"Which sentence describes a problem on a call right now?","options":["My microphone is not working.","My microphone did not work.","My microphone works well."],"correct":0},{"from":"int-1","kind":"mcq","prompt":"Which sentence is best for the \"now\" part of an introduction?","options":["I was born in Tabriz, and I still live there.","I currently work as a sales assistant in a phone shop.","I like football and films, and I love meeting people."],"correct":1}]},"explain":{"id":"c-int-9-e","course":"interview","unit":"int-9","type":"explain","level":"B1","title":{"en":"The offer and the numbers","tr":"Teklif ve rakamlar","fa":"پیشنهاد کار و عددها"},"objective":{"en":"In this lesson you will learn to answer a job offer, check the package and ask for a change politely.","tr":"Bu derste bir iş teklifine cevap vermeyi, ücret paketini kontrol etmeyi ve kibarca değişiklik istemeyi öğreneceksin.","fa":"در این درس یاد می‌گیری به پیشنهاد کار جواب بدهی، بسته‌ی حقوق و مزایا را بررسی کنی و مؤدبانه یک تغییر بخواهی."},"hook":{"en":"The offer is good news. It is also the moment you have the most to read and decide.","tr":"Teklif iyi haberdir. Aynı zamanda en çok şey okuyup karar vereceğin andır.","fa":"پیشنهاد کار خبر خوبی است، اما لحظه‌ای هم هست که باید بیشترین مطالب را بخوانی و درباره‌شان تصمیم بگیری."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Don't say yes in the first second","tr":"İlk saniyede evet deme","fa":"در ثانیه‌ی اول بله نگو"},"steps":[{"en":"Thank them. Ask for the offer in writing, and a day to reply.","tr":"Teşekkür et. Teklifi yazılı olarak iste ve cevap için bir gün süre al.","fa":"تشکر کن. پیشنهاد را کتبی بخواه و برای جواب یک روز وقت بگیر.","ex":"Could you send it in writing? I'll reply by Thursday."},{"en":"Read all of it: pay, hours, overtime, probation, notice, start date.","tr":"Hepsini oku: maaş, saatler, fazla mesai, deneme süresi, ihbar süresi, başlama tarihi.","fa":"همه را بخوان: حقوق، ساعت کار، اضافه‌کاری، دوره‌ی آزمایشی، مدت پیش‌آگهی، تاریخ شروع.","ex":"Is the basic salary before or after tax?"},{"en":"Choose what matters most. Ask in one message, most important first.","tr":"En önemlisini seç. Tek mesajda, en önemlisi başta olacak şekilde iste.","fa":"مهم‌ترین خواسته را انتخاب کن. همه را در یک پیام مطرح کن و مهم‌ترین را اول بگو.","ex":"First the start date, then the training budget"},{"en":"Give a reason for each request, and show you still want the job.","tr":"Her istek için bir neden ver ve işi hâlâ istediğini göster.","fa":"برای هر خواسته دلیل بیاور و نشان بده هنوز این کار را می‌خواهی.","ex":"My notice is four weeks, so could I start on 3 April?"}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Asking politely: I was hoping, Would it be possible","tr":"Kibarca istemek: I was hoping, Would it be possible","fa":"درخواست مؤدبانه: I was hoping و Would it be possible"},"steps":[{"en":"A soft request: I was hoping... could...","tr":"Yumuşak bir rica: I was hoping... could...","fa":"درخواست نرم: I was hoping... could...‎","ex":"I was hoping you could cover my flight."},{"en":"A soft question: I was wondering if...","tr":"Yumuşak bir soru: I was wondering if...","fa":"سؤال نرم: I was wondering if...‎","ex":"I was wondering if overtime is paid."},{"en":"Would it be possible to + verb?","tr":"Would it be possible to + fiil?","fa":"Would it be possible to + فعل؟","ex":"Would it be possible to start on 3 April?"}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["I was hoping + could","I was hoping you could cover my flight."],["I was wondering if...","I was wondering if overtime is paid."],["Would it be possible to + verb?","Would it be possible to start on 3 April?"]]},"tip":{"en":"Turkish 'istiyorum ki ödeyesiniz' and Persian 'می‌خواهم که بپردازید' give the calque 'I want that you pay', which sounds rude. English softens with the past (I was hoping) and with would.","tr":"Türkçedeki 'istiyorum ki...' yapısı 'I want that you pay' gibi bir çeviriye yol açar ve kaba duyulur. İngilizce geçmiş zamanla (I was hoping) ve would ile yumuşatır.","fa":"ساختار «می‌خواهم که...» در فارسی به ترجمه‌ی «I want that you pay» می‌رسد که بی‌ادبانه است. انگلیسی با زمان گذشته (I was hoping) و با would لحن را نرم می‌کند."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"If the answer is no","tr":"Cevap hayırsa","fa":"اگر جواب منفی بود"},"body":{"en":"Some things can't change, so accept that without threats. If you don't get the job, reply in three lines: thanks, one question about what you could improve, and that you would like to stay in touch.","tr":"Bazı şeyler değişemez; bunu tehdit etmeden kabul et. İşi alamazsan üç satırla cevap ver: teşekkür, neyi geliştirebileceğine dair bir soru ve iletişimde kalmak istediğin.","fa":"بعضی چیزها عوض نمی‌شوند؛ این را بدون تهدید بپذیر. اگر کار را نگرفتی، در سه خط جواب بده: تشکر، یک سؤال درباره‌ی اینکه چه چیزی را می‌توانی بهتر کنی و اینکه دوست داری در تماس بمانی."},"phrases":[{"phrase":"Thank you so much for the offer.","meaning":{"en":"Your first sentence, before any question.","tr":"Her sorudan önce ilk cümlen.","fa":"جمله‌ی اولت، قبل از هر سؤال."}},{"phrase":"I was hoping... Would that be possible?","meaning":{"en":"Asks for a change without pushing.","tr":"Baskı yapmadan değişiklik ister.","fa":"بدون فشار یک تغییر می‌خواهد."}},{"phrase":"I'll get back to you by...","meaning":{"en":"Gives yourself time, with a date.","tr":"Bir tarih vererek kendine zaman tanır.","fa":"با گفتن تاریخ به خودت وقت می‌دهد."}},{"phrase":"in writing","meaning":{"en":"Written down, not only said.","tr":"yazılı olarak.","fa":"به‌صورت کتبی"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Ask without pushing","tr":"Baskı yapmadan iste","fa":"بدون فشار بخواه"},"item":"I want more money. Everybody pays more than you. Your facts: you would love the job; pay data for this role shows about 5,000 lira more.","answer":"Thank you so much for the offer. I'd love to join you. Based on what I found for this role, I was hoping for 5,000 lira more. Would that be possible?","walk":[{"en":"Start with thanks and interest.","tr":"Teşekkür ve ilgiyle başla.","fa":"با تشکر و علاقه شروع کن."},{"en":"Give your reason, based on real pay data.","tr":"Gerçek ücret bilgisine dayanan nedenini söyle.","fa":"دلیلت را بر اساس اطلاعات واقعی حقوق بگو."},{"en":"Ask with \"I was hoping\" and a clear number.","tr":"\"I was hoping\" ve net bir sayıyla iste.","fa":"با «I was hoping» و یک عدد روشن بخواه."}]},"quick":{"prompt":"Would it be possible ___ next Monday instead?","options":["to begin","to beginning","beginning"],"correct":0,"why":{"en":"to begin: after \"Would it be possible\" use to + verb, not -ing.","tr":"to begin: \"Would it be possible\" ifadesinden sonra -ing değil, to + fiil gelir.","fa":"to begin: بعد از «Would it be possible» باید to + فعل بیاید، نه ‎-ing."}},"remember":{"en":"Happy first, reason second, everything in one message.","tr":"Önce sevinç, sonra neden, hepsi tek mesajda.","fa":"اول خوشحالی، بعد دلیل، همه در یک پیام."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Offering a trade: If you could..., I'd be happy to...","tr":"Takas önermek: If you could..., I'd be happy to...","fa":"پیشنهاد معامله: If you could..., I'd be happy to..."},"steps":[{"en":"Propose: If you could..., I would...","tr":"Öner: If you could..., I would...","fa":"پیشنهاد بده: If you could..., I would...‎","ex":"If you could cover my flight, I'd be happy to start early."},{"en":"I'd be happy to: don't drop be.","tr":"I'd be happy to: be'yi düşürme.","fa":"I'd be happy to: کلمه‌ی be را جا نینداز.","ex":"I'd be happy to start on 28 March."},{"en":"Close the deal: If + present, will.","tr":"Anlaşmayı bağla: If + present, will.","fa":"توافق را نهایی کن: If + حال ساده، will.","ex":"If you send the contract today, I will sign it on Monday."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Proposal: If you could..., I'd...","If you could cover my flight, I'd be happy to start early."],["I'd be happy to + verb (with be)","I'd be happy to start on 28 March."],["Closing the deal: If + present, will","If you send the contract today, I will sign it on Monday."]]},"body":{"en":"B2: in your reply to the offer, propose one small trade with 'If you could..., I'd be happy to...'.","tr":"B2: teklife cevabında 'If you could..., I'd be happy to...' ile küçük bir takas öner.","fa":"B2: در جوابت به پیشنهاد کار، با «If you could..., I'd be happy to...‎» یک معامله‌ی کوچک پیشنهاد بده."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
